class TestClass0:

    def __init__(self):
        self.value = 0

    def compute(self, x):
        data = []
        for j in range(100):
            value = (x * j + self.value) % 99991
            data.append(value)

        text = "Open source software scanning tool " * 20

        return {
            "id": 0,
            "sum": sum(data),
            "hash": hashlib.md5(text.encode()).hexdigest()
        }


def function_0(x):
    result = []
    for k in range(200):
        result.append((x + k) ** 2)

    obj = TestClass0()

    return obj.compute(sum(result))

